import { useState } from 'react';
import { JxTagInput } from '@jinx-ui/react';

interface ArticleTagInputProps {
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagInput({ defaultValue = [], onChange }: ArticleTagInputProps) {
  const [tags, setTags] = useState<string[]>(defaultValue);

  const handleValueChange = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-gap, 8px)' }}>
      <span className="jx-label">Теги статьи</span>
      <JxTagInput
        ariaLabel="Теги статьи"
        placeholder="Введите тег и нажмите Enter"
        value={tags}
        onValueChange={handleValueChange}
      />
      <p className="jx-input-help">
        {tags.length > 0
          ? `Добавлено тегов: ${tags.length}. Нажмите крестик на метке, чтобы удалить тег.`
          : 'Пока нет тегов — введите слово и нажмите Enter.'}
      </p>
    </div>
  );
}

